"""Final validation: ensure candidates work with a mock solve call."""

import sys
import importlib.util

def test_candidate(name):
    """Load and test a candidate harness."""
    print(f"\nTesting {name}...")
    print("-" * 50)

    # Load the harness module
    harness_path = f"agents/{name}/harness.py"
    spec = importlib.util.spec_from_file_location("harness", harness_path)
    harness = importlib.util.module_from_spec(spec)

    try:
        spec.loader.exec_module(harness)
    except Exception as e:
        print(f"❌ Failed to load: {e}")
        return False

    # Check solve function exists
    if not hasattr(harness, 'solve'):
        print("❌ No solve function")
        return False

    # Create mock objects
    class MockLLM:
        def __call__(self, prompt, system=None):
            return "ANSWER: test"

    class MockTools:
        def python(self, code):
            return "output"

    class MockFiles:
        def __init__(self):
            self.data = {}
            # Load actual prompts
            try:
                with open(f"agents/{name}/prompts/system.md") as f:
                    self.data["prompts/system.md"] = f.read()
                with open(f"agents/{name}/prompts/task.md") as f:
                    self.data["prompts/task.md"] = f.read()
            except Exception as e:
                print(f"❌ Failed to load prompts: {e}")
                return False

        def get(self, key, default=""):
            return self.data.get(key, default)

        def __getitem__(self, key):
            return self.data[key]

    # Test with mock data
    try:
        files = MockFiles()
        result = harness.solve("What is 2+2?", MockLLM(), MockTools(), files)

        if isinstance(result, str) and result:
            print(f"✅ solve() executed successfully")
            print(f"   Result: {result[:50]}...")
            return True
